<style>
    .rts__breadcrumb__content{position:relative;overflow:hidden;z-index:1}.rts__breadcrumb__content:before{content:"";position:absolute;inset:0;background:rgba(0,0,0,.5);z-index:-1;border-radius:inherit}.rts__breadcrumb__content .list,.rts__breadcrumb__content .title{position:relative;z-index:2}.company-page-image{width:100%;height:500px;object-fit:cover;border-radius:18px}.company-feature-card{height:100%;padding:34px 28px;background:#fff;border:1px solid rgba(0,37,36,.08);border-radius:16px;box-shadow:0 10px 35px rgba(0,37,36,.06);transition:.3s}.company-feature-card:hover{transform:translateY(-7px);border-color:#34A853}.company-feature-card>i{width:52px;height:52px;display:flex;align-items:center;justify-content:center;border-radius:12px;background:rgba(52,168,83,.12);color:#34A853;font-size:22px;margin-bottom:22px}.company-feature-card h4{margin-bottom:12px}.company-feature-card p{margin:0;color:#596665}.company-project-card{height:100%;background:#fff;border-radius:18px;overflow:hidden;border:1px solid rgba(0,37,36,.07);box-shadow:0 12px 40px rgba(0,37,36,.07)}.company-project-card img{width:100%;height:300px;object-fit:cover}.company-project-card .content{padding:30px}.company-project-card .content span{color:#34A853;font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:1px}.company-project-card .content h3{margin:10px 0}.company-project-card .content a{color:#002524;font-weight:700}.company-project-card .content a:hover{color:#34A853}@media(max-width:767px){.company-page-image{height:320px}}
